// Centre-orientation fixing for the Axis Cube.
//
// On a normal 3x3 the centres' rotation is invisible, on the Axis Cube it is
// not (the centres are asymmetric two-colour pieces). After the corners and
// edges are solved, the remaining centre twists are fixed with algorithms that
// leave every corner and edge in place. The base algorithms below were found
// by computer search; all symmetric variants are generated by whole-cube
// rotations and verified by simulation, then the cheapest combination for a
// given residual is chosen by Dijkstra over the 4^6 centre states.

import { CubeState, FACE_ORDER, faceDir, apply, ROTATIONS, parseAlg, centerTwist } from '../cube.js';
import { toCubieCube } from './bridge.js';

const BASE_ALGS = [
  "U R L U2 R' L' U R L U2 R' L'", // U2
  "U2 R L' B2 D2 F2 L R' D2 B2", // U2 + F2
  "U2 R2 F2 B2 L2 D2 L2 B2 F2 R2", // U2 + D2
  "U R L F2 B2 R' L' D' R L F2 B2 R' L'", // U+ D-
  "F B R' L U' D' F D U L' R B' F' U'", // F+ U-
];

const dirKey = (v) => v.join(',');
const FACE_BY_DIR = new Map(FACE_ORDER.map((f) => [dirKey(faceDir(f)), f]));

function rotateAlg(moves, g) {
  return moves.map(({ face, turns }) => ({ face: FACE_BY_DIR.get(dirKey(apply(g, faceDir(face)))), turns }));
}

function effect(moves) {
  const s = new CubeState();
  for (const m of moves) s.move(m.face, m.turns);
  const c = toCubieCube(s);
  const clean =
    c.cp.every((v, i) => v === i) &&
    c.ep.every((v, i) => v === i) &&
    c.co.every((v) => v === 0) &&
    c.eo.every((v) => v === 0);
  return clean ? FACE_ORDER.map((f) => centerTwist(s, f)) : null;
}

const encode = (tw) => tw.reduce((a, v) => a * 4 + v, 0);
const decode = (code) => {
  const tw = [];
  for (let i = 5; i >= 0; i--) {
    tw[i] = code & 3;
    code >>= 2;
  }
  return tw;
};

let LIB = null;
function library() {
  if (LIB) return LIB;
  const seen = new Map(); // effect code -> moves (shortest)
  for (const src of BASE_ALGS) {
    const base = parseAlg(src);
    for (const g of ROTATIONS) {
      for (const moves of [rotateAlg(base, g), rotateAlg(invert(base), g)]) {
        const eff = effect(moves);
        if (!eff) throw new Error(`Centre algorithm does not preserve cubies: ${src}`);
        const code = encode(eff);
        if (code === 0) continue;
        if (!seen.has(code) || seen.get(code).length > moves.length) seen.set(code, moves);
      }
    }
  }
  LIB = [...seen.entries()].map(([code, moves]) => ({ eff: decode(code), moves }));
  return LIB;
}

function invert(moves) {
  return moves
    .slice()
    .reverse()
    .map(({ face, turns }) => ({ face, turns: turns === 2 ? 2 : -turns }));
}

// One Dijkstra from the solved state: dist[x] = fewest moves of library
// algorithms whose combined effect twists the centres by x.
let DIJ = null;
function table() {
  if (DIJ) return DIJ;
  const lib = library();
  const N = 4096;
  const dist = new Float64Array(N).fill(Infinity);
  const prev = new Int32Array(N).fill(-1);
  const via = new Int32Array(N).fill(-1);
  const done = new Uint8Array(N);
  dist[0] = 0;
  for (;;) {
    let u = -1;
    for (let i = 0; i < N; i++) if (!done[i] && dist[i] < Infinity && (u < 0 || dist[i] < dist[u])) u = i;
    if (u < 0) break;
    done[u] = 1;
    const tw = decode(u);
    lib.forEach((a, k) => {
      const v = encode(tw.map((t, i) => (t + a.eff[i]) % 4));
      const d = dist[u] + a.moves.length;
      if (d < dist[v]) {
        dist[v] = d;
        prev[v] = u;
        via[v] = k;
      }
    });
  }
  DIJ = { dist, prev, via, lib };
  return DIJ;
}

const negate = (twists) => encode(twists.map((t) => (4 - t) % 4));

// Number of moves needed to undo the given centre twists.
export function centerFixCost(twists) {
  return table().dist[negate(twists)];
}

// Moves (grouped per algorithm) that bring the given centre twists (clockwise
// quarter turns per face, FACE_ORDER) back to zero without disturbing corners
// or edges.
export function centerFix(twists) {
  const { dist, prev, via, lib } = table();
  const target = negate(twists);
  if (dist[target] === Infinity) throw new Error('Centre twists are not solvable (odd total twist)');
  const chunks = [];
  for (let v = target; v !== 0; v = prev[v]) chunks.unshift(lib[via[v]].moves);
  return chunks;
}
